(* [comment removed for export] *)
Lemma finish_rs (fx : FPState) R M model s sm cr (ptr n : Z) :
  getr R (reg 1) = Z_to_bv 64 (bv_unsigned (getr R0 (reg 1))) -> getr R (reg 2) = Z_to_bv 64 S ->
  getr R (reg 8) = Z_to_bv 64 (bv_unsigned (getr R0 (reg 8))) -> getr R (reg 9) = Z_to_bv 64 (bv_unsigned (getr R0 (reg 9))) ->
  getr R (reg 18) = Z_to_bv 64 (bv_unsigned (getr R0 (reg 18))) -> kept_rs R ->
  getr R (reg 10) = Z_to_bv 64 ptr -> getr R (reg 11) = Z_to_bv 64 n -> 0 <= n <= len -> n < 2 ^ 26 ->
  ((ptr = 0 /\ n = 0) \/ (exists B m, In (B, m) (PM.parser_own s) /\ B <= ptr /\ ptr + n <= B + m) \/ (fb + 384 + 1 <= ptr /\ ptr + n <= fb + 384 + 24)) ->
  L5.defined M ptr n ->
  L5.bytes_at RSEGS M ptr (UbjRef.slice pl (PEC.pos_of pl (PM.p_src s0) sm0) n) -> n = Z.min len (blen pl - PEC.pos_of pl (PM.p_src s0) sm0) ->
  PMSP.consumed (PM.p_src s0) (PM.p_src s) sm0 sm = n ->
  st_ok M model s sm cr -> PECSRK.fields_eq s0 s -> PMSP.src_step (PM.p_src s0) (PM.p_src s) sm0 sm ->
