(* [comment removed for export] *)
(* [comment removed for export] *)
Lemma call_fill (fx : FPState) R M model s sm cr (X : Z) :
  getr R (reg 1) = Z_to_bv 64 X -> L5.ra_ok X -> getr R (reg 2) = Z_to_bv 64 (S - 32) -> kept_rs R ->
  getr R (reg 10) = Z_to_bv 64 (fb + 72) -> getr R (reg 11) = Z_to_bv 64 (PM.sr_qc (PM.p_src s)) -> getr R (reg 12) = Z_to_bv 64 PM.CHUNK ->
  st_ok M model s sm cr -> PM.sr_rem (PM.p_src s) = 0 ->
  (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (sm' : PM.strm) (c : Z),
     regs_preserved R R' -> getr R' (reg 10) = Z_to_bv 64 c -> 0 <= c <= PM.CHUNK -> PM.sm_g sm' = PM.sm_g sm + c ->
     (c < PM.CHUNK -> PM.sm_g sm' = PM.sm_eg sm /\ PM.sm_st sm' = 2) -> (PM.sm_st sm = 2 -> c = 0) ->
     L5.bytes_at RSEGS M' (PM.sr_qc (PM.p_src s)) (UbjRef.slice pl (blen pl - (PM.sm_eg sm - PM.sm_g sm)) c) ->
     (PM.sm_st sm' = 2 -> PM.sm_g sm' = PM.sm_eg sm') ->
     PMSP.src_step (PM.p_src s) (PM.p_src s) sm sm' ->
     st_ok M' model s sm' cr ->
     srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx' R' X M' model) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx R 0x39310 M model) K.
Proof using All.
